    def setting_added(self):

        dlg = QtWidgets.QMessageBox(self)
        
        dlg.setWindowTitle("Done!")
        
        dlg.setText("<font color = '#335674'>The current setting was saved! You can create a new one or go to Generate Dataset\
                    to generate a synthetic dataset with all saved settings.</font color = '#335674'>")
        
        button = dlg.exec()

    def add_class_warning(self):

        dlg = QtWidgets.QMessageBox(self)
        
        dlg.setWindowTitle("Warning!")
        
        dlg.setText("<font color = '#335674'>Adding class is a tool for multiclass classification/segmentation algorithms.\
                    If you are only interested in segmenting particle from background, you should create all your settings \
                    with the same class name (e.g. \"particle\").</font color = '#335674'>")
        
        button = dlg.exec()

    def handle_particle_type(self):

        if self.comboBoxParticleType.currentText() in ['Silica', 'Polygon', 'Gold']:
            
            self.spinBoxNumofVerticesmin.setVisible(True)
            self.label_to_NumOfVertices.setVisible(True)
            self.spinBoxNumofVerticesmax.setVisible(True)
            self.labelNumOfVertices.setVisible(True)
            self.doublespinBoxPolymerIrregularity.setVisible(True)
            self.labelPolymerIrregularity.setVisible(True)
        
        else:
            self.spinBoxNumofVerticesmin.setVisible(False)
            self.label_to_NumOfVertices.setVisible(False)
            self.spinBoxNumofVerticesmax.setVisible(False)
            self.labelNumOfVertices.setVisible(False)
            self.doublespinBoxPolymerIrregularity.setVisible(False)
            self.labelPolymerIrregularity.setVisible(False)

    def check_selections(self, push_button_type):

        selected1 = self.comboBoxGrid.currentText()

        selected2 = self.comboBoxParticleType.currentText()

        selected3 = self.comboBoxParticleNoise.currentText()

        kernel_size_value = self.spinBoxIlluminationKernelSize.value() # Only odd numbers are allowed
        
        if (selected1 == "") or (selected2 == "") or (selected3 == ""):

            missing_fields = []

            if selected1 == "":

                missing_fields.append("Missing Grid Type Selection")

            if selected2 == "":

                missing_fields.append("Missing Particle Type Selection")

            if selected3 == "":

                missing_fields.append("Missing Particle Noise Selection")

            error_message = "- " + "\n".join(missing_fields)

            QtWidgets.QMessageBox.warning(self, "Selection Error", error_message)
        
        elif (kernel_size_value % 2 == 0):

            QtWidgets.QMessageBox.warning(self, "Kernel Size Error", "Kernel size must be an odd number.")
        
        else:

            if push_button_type == 'plot':

                self.plot_image_thread()

            if push_button_type == 'save':

                self.save_setting()

    def handle_bg_type(self):

        if self.comboBoxGrid.currentText() == "Experimental Background": 
            
            self.checkBoxSliceExpBg.setVisible(True)

            self.checkBoxRestrict2carbon.setVisible(False)

            self.checkBoxRestrict2Holes.setVisible(False)
            
            file_dialog = QtWidgets.QFileDialog(directory='./')
            
            file_dialog.setFileMode(QtWidgets.QFileDialog.FileMode.Directory)
           
            if file_dialog.exec() == QtWidgets.QFileDialog.DialogCode.Accepted:
                
                self.dir_path  = file_dialog.selectedFiles()[0]
        
        elif self.comboBoxGrid.currentText() == "Holey Carbon" or self.comboBoxGrid.currentText() == "Lacey Carbon": 
            
            self.checkBoxRestrict2carbon.setVisible(True)

            self.checkBoxRestrict2Holes.setVisible(True)

            self.checkBoxSliceExpBg.setVisible(False)

        else:

            self.checkBoxRestrict2carbon.setVisible(False)

            self.checkBoxRestrict2Holes.setVisible(False)
            
            self.checkBoxSliceExpBg.setVisible(False)

        
    def show_particle_noise_weigh(self):

        if self.comboBoxParticleNoise.currentText() != "None": 

            self.doubleSpinBoxParticleNoiseWeight.setVisible(True)  

            self.pushButtonParticleNoiseAdvancedSettings.setVisible(True)            

            self.labelParticleNoiseWeight.setVisible(True)  

        else:  

            self.doubleSpinBoxParticleNoiseWeight.setVisible(False)  

            self.pushButtonParticleNoiseAdvancedSettings.setVisible(False)

            self.labelParticleNoiseWeight.setVisible(False) 

    def show_image_noise_weigh(self):

        if self.comboBoxImageNoise.currentText() != "None":  

            self.doubleSpinBoxImageNoiseWeight.setVisible(True)  

            self.pushButtonImageNoiseAdvancedSettings.setVisible(True)

            self.labelImageNoiseWeight.setVisible(True)  

        else:  

            self.doubleSpinBoxImageNoiseWeight.setVisible(False) 

            self.pushButtonImageNoiseAdvancedSettings.setVisible(False) 

            self.labelImageNoiseWeight.setVisible(False) 
    

    # Only show Rescale Probability if the option is checked. Hide if unchecked
    def handle_checkbox(self, state, *widgets):
        
        # Show or hide the double spin box based on the checkbox state
        if state == 2:  # Checked
            
            for widget in widgets:
               
                widget.setVisible(True)
                
                if widget == self.QLineEditAddClass:
                    
                    self.add_class_warning()
 
        else:  # Unchecked
            
            for widget in widgets:
                
                widget.setVisible(False)

    
    # Don't allow minimum value to be bigger than maximum
    def handle_intervals(self, min_spin_box, max_spin_box):

        min_value = min_spin_box.value()
       
        max_value = max_spin_box.value()

        if min_value >= max_value:
            
            if self.sender() == min_spin_box:
                
                max_spin_box.setValue(min_value + 1)
           
            else:
               
                min_spin_box.setValue(max_value - 1)

    # Save Settings dictionary if the button is clicked
    def save_setting(self):
        # Get settings
        new_entry = self.get_settings()
        # Add to dictionary
        self.data_store.data_dict[str(self.button_click_count)] = new_entry[0]
        # Increment the button click count, as it is used as key   
        self.button_click_count += 1
        
        print(f"Current dictionary: {self.data_store.data_dict}")

    def noise_advanced_settings(self):

        dialog = NoiseInputDialog(self.frequency, 
                             self.noise_octaves, 
                             self.noise_gain,
                             self.noise_lacunarity)

